public class Alumno {
    private String nombre;
    private String email;
    private double notaMedia;

    public Alumno(String nombre, String email) {
        this.nombre = nombre;
        this.email = email;
        this.notaMedia = 0.0;
    }

    public String getNombre() { return nombre; }
    public String getEmail() { return email; }
    public double getNotaMedia() { return notaMedia; }
    public void setNotaMedia(double nota) { this.notaMedia = nota; }

    public boolean estaAprobado() {
        return notaMedia >= 5.0;
    }

    public String getCalificacion() {
        if (notaMedia >= 9) return "Sobresaliente";
        if (notaMedia >= 7) return "Notable";
        if (notaMedia >= 5) return "Aprobado";
        return "Suspenso";
    }

    @Override
    public String toString() {
        return nombre + " (" + email + ") - Nota: " + String.format("%.1f", notaMedia);
    }
}

public class AlumnoBecario extends Alumno {
    // Campos propios de AlumnoBecario
    private String numBeca;
    private double porcentajeDescuento;

    // Constructor: llama al constructor de Alumno con super()
    public AlumnoBecario(String nombre, String email, String numBeca, double descuento) {
        super(nombre, email);  // Llama al constructor de Alumno
        this.numBeca = numBeca;
        this.porcentajeDescuento = descuento;
    }

    // Getters propios
    public String getNumBeca() { return numBeca; }
    public double getPorcentajeDescuento() { return porcentajeDescuento; }

    // Metodo propio
    public double calcularCuotaDescuento(double cuotaBase) {
        return cuotaBase * (1 - porcentajeDescuento / 100);
    }

    @Override
    public String toString() {
        return super.toString() + " [Beca: " + numBeca + ", Descuento: " + porcentajeDescuento + "%]";
    }
}

public class GestionAlumnos {
    public static void main(String[] args) {
        // Alumno normal
        Alumno ana = new Alumno("Ana", "ana@email.com");
        ana.setNotaMedia(8.5);

        // Alumno becario (hereda de Alumno)
        AlumnoBecario carlos = new AlumnoBecario(
            "Carlos", "carlos@email.com", "BEC-2026-001", 25.0
        );
        carlos.setNotaMedia(7.0);

        // AlumnoBecario TAMBIEN es un Alumno
        System.out.println("Ana: " + ana);
        System.out.println("Carlos: " + carlos);

        // Metodos heredados funcionan igual
        System.out.println("Ana aprobada: " + ana.estaAprobado());
        System.out.println("Carlos aprobado: " + carlos.estaAprobado());

        // Metodo propio de AlumnoBecario
        double cuotaBase = 1000.0;
        System.out.println("Cuota Carlos (con beca): " + carlos.calcularCuotaDescuento(cuotaBase) + " EUR");

        // Polimorfismo basico: un AlumnoBecario puede usarse donde se espere un Alumno
        Alumno referencia = carlos; // OK: AlumnoBecario es un Alumno
        System.out.println("Referencia: " + referencia.getNombre());
    }
}

public class AlumnoBecario extends Alumno {
    private String numBeca;
    private double descuento;

    public AlumnoBecario(String nombre, String email, String numBeca, double descuento) {
        super(nombre, email);
        this.numBeca = numBeca;
        this.descuento = descuento;
    }

    // No podemos hacer: this.nombre = "X"; (nombre es private en Alumno)
    // Pero si podemos: getNombre() (heredado de Alumno)

    @Override
    public String toString() {
        // Usamos getNombre() para acceder al nombre privado de la superclase
        return getNombre() + " [Beca: " + numBeca + ", Descuento: " + descuento + "%]";
    }

    // Metodo que combina datos heredados y propios
    public String getInfoCompleta() {
        return getNombre() + " | " + getEmail()
             + " | Nota: " + getNotaMedia()
             + " | Beca: " + numBeca
             + " | Descuento: " + descuento + "%";
    }
}

