        this.tasaInteres = tasaInteres;
    }

    public double calcularInteres() {
        return getSaldo() * tasaInteres / 100;
    }

    @Override
    public String getDescripcion() {
        return super.getDescripcion() + " | Interes: " + tasaInteres + "%";
    }
}

public class CuentaAhorroPremium extends CuentaAhorro {
    private double tasaExtra;

    public CuentaAhorroPremium(String titular, double saldo, double tasaInteres, double tasaExtra) {
        super(titular, saldo, tasaInteres);
        this.tasaExtra = tasaExtra;
    }

    @Override
    public double calcularInteres() {
        return super.calcularInteres() + (getSaldo() * tasaExtra / 100);
    }

    @Override
    public String getDescripcion() {
        return super.getDescripcion() + " + " + tasaExtra + "% extra";
    }

    public static void main(String[] args) {
        CuentaAhorroPremium c = new CuentaAhorroPremium("Ana", 10000, 2.0, 1.5);
        System.out.println(c.getDescripcion());
        System.out.println("Interes total: " + String.format("%.2f", c.calcularInteres()) + " EUR");
    }
}

