    public Alumno(String nombre, double notaMedia) {
        super(nombre);
        this.notaMedia = notaMedia;
    }

    public double getNotaMedia() { return notaMedia; }

    @Override
    public String getRol() { return "Alumno"; }

    @Override
    public String saludar() {
        return super.saludar() + ", y soy alumno con nota " + String.format("%.1f", notaMedia);
    }
}

public class Profesor extends Persona {
    private String departamento;

    public Profesor(String nombre, String departamento) {
        super(nombre);
        this.departamento = departamento;
    }

    @Override
    public String getRol() { return "Profesor"; }

    @Override
    public String saludar() {
        return super.saludar() + ", y soy profesor de " + departamento;
    }
}

public class DemoRoles {
    public static void main(String[] args) {
        Persona[] personas = {
            new Persona("Ana"),
            new Alumno("Carlos", 8.5),
            new Profesor("Maria", "Informatica")
        };

        for (Persona p : personas) {
            System.out.println(p);         // toString() sobrescrito
            System.out.println(p.saludar()); // saludar() sobrescrito
            System.out.println("Rol: " + p.getRol());
            System.out.println();
        }
    }
}

