        this.nombre = nombre;
        this.salarioBase = salarioBase;
    }

    public double getSalarioTotal() { return salarioBase; }

    @Override
    public String toString() {
        return nombre + " | Salario: " + String.format("%.2f", getSalarioTotal()) + " EUR";
    }
}

public class EmpleadoComision extends Empleado {
    private double porcentajeComision;
    private double ventas;

    public EmpleadoComision(String nombre, double salarioBase, double comision, double ventas) {
        super(nombre, salarioBase);
        this.porcentajeComision = comision;
        this.ventas = ventas;
    }

    @Override
    public double getSalarioTotal() {
        double comision = ventas * porcentajeComision / 100;
        return super.getSalarioTotal() + comision;
    }
}

public class EmpleadoDirector extends Empleado {
