public class CuentaBancaria {
    protected String titular;
    protected double saldo;

    public CuentaBancaria(String titular, double saldo) {
        this.titular = titular;
        this.saldo = saldo;
    }

    public double getSaldo() { return saldo; }

    public void retirar(double cantidad) {
        if (cantidad <= 0) { System.out.println("Cantidad invalida"); return; }
        if (cantidad > saldo) { System.out.println("Saldo insuficiente"); return; }
        saldo -= cantidad;
        System.out.println("Retirado: " + cantidad + " EUR. Saldo: " + saldo);
    }
}

public class CuentaConLimite extends CuentaBancaria {
    private double limiteDiario;
    private double retiradoHoy;

    public CuentaConLimite(String titular, double saldo, double limiteDiario) {
        super(titular, saldo);
        this.limiteDiario = limiteDiario;
        this.retiradoHoy = 0;
    }

    @Override
    public void retirar(double cantidad) {
        if (retiradoHoy + cantidad > limiteDiario) {
            System.out.println("Excede el limite diario de " + limiteDiario + " EUR");
            return;
        }
        super.retirar(cantidad);
        retiradoHoy += cantidad;
    }
}

public class CuentaPremium extends CuentaBancaria {
    private double limiteDescubierto;

    public CuentaPremium(String titular, double saldo, double limiteDescubierto) {
        super(titular, saldo);
        this.limiteDescubierto = limiteDescubierto;
    }

    @Override
    public void retirar(double cantidad) {
        if (cantidad <= 0) { System.out.println("Cantidad invalida"); return; }
        if (cantidad > saldo + limiteDescubierto) {
            System.out.println("Excede el descubierto permitido");
            return;
        }
        saldo -= cantidad;
        System.out.println("Retirado: " + cantidad + " EUR. Saldo: " + saldo);
    }
