public abstract class Empleado {
    protected String nombre;
    protected double salarioBase;

    public Empleado(String nombre, double salarioBase) {
        this.nombre = nombre;
        this.salarioBase = salarioBase;
    }

    public abstract double calcularSalario();

    public String getDescripcion() {
        return nombre + " | Salario: " + String.format("%.2f", calcularSalario()) + " EUR";
    }
}

public class EmpleadoFijo extends Empleado {
    public EmpleadoFijo(String nombre, double salarioBase) {
        super(nombre, salarioBase);
    }

    @Override
    public double calcularSalario() {
        return salarioBase; // Sin cambios
    }
}

public class EmpleadoTemporal extends Empleado {
    private int horasTrabajadas;
    private double precioHora;

    public EmpleadoTemporal(String nombre, double salarioBase, int horas, double precioHora) {
        super(nombre, salarioBase);
        this.horasTrabajadas = horas;
        this.precioHora = precioHora;
    }

    @Override
    public double calcularSalario() {
        return horasTrabajadas * precioHora;
    }

