        System.out.println(e2.getDescripcion());
    }
}

public abstract class Forma {
    protected String nombre;
    public Forma(String nombre) { this.nombre = nombre; }
    public abstract double calcularArea();
    @Override
    public String toString() { return nombre + " [Area: " + String.format("%.2f", calcularArea()) + "]"; }
}

public class Cuadrado extends Forma {
    protected double lado;
    public Cuadrado(double lado) {
        super("Cuadrado");
        this.lado = lado;
    }
    @Override
    public final double calcularArea() { return lado * lado; } // final: no sobrescribible
}

public class CuadradoMagico extends Cuadrado {
    private String magia;
    public CuadradoMagico(double lado, String magia) {
        super(lado);
        this.nombre = "Cuadrado Magico";
        this.magia = magia;
    }
    public String getMagia() { return magia; }
    // calcularArea() NO se puede sobrescribir (es final en Cuadrado)
    @Override
    public String toString() { return nombre + " [Magia: " + magia + ", Area: " + String.format("%.2f", calcularArea()) + "]"; }
}

public class Circulo extends Forma {
    private double radio;
    public Circulo(double radio) { super("Circulo"); this.radio = radio; }
    @Override
    public double calcularArea() { return Math.PI * radio * radio; }
}

